<script setup lang="ts">import type{CoverConfig}from'../../core/models';defineProps<{config:CoverConfig;title:string;editing:boolean;saving?:boolean}>();const emit=defineEmits<{patch:[p:Partial<CoverConfig>];title:[t:string];save:[mode:'update'|'copy']}>();</script>
<template><section class="cover-layout"><div class="stage-card controls"><span class="kicker">04 / COVER LAB</span><h2>给声音穿件有戏的外套</h2><label>作品名称<input :value="title" @input="emit('title',($event.target as HTMLInputElement).value)"></label><label>气泡文字<textarea aria-label="气泡文字" :value="config.bubbleText" @input="emit('patch',{bubbleText:($event.target as HTMLTextAreaElement).value})"></textarea></label><label>滤镜<select :value="config.filter" @change="emit('patch',{filter:($event.target as HTMLSelectElement).value as CoverConfig['filter']})"><option value="none">原色</option><option value="mono">黑白</option><option value="saturate">高饱和</option><option value="warm">暖调</option><option value="cool">冷调</option></select></label><label>比例<select :value="config.ratio" @change="emit('patch',{ratio:($event.target as HTMLSelectElement).value as CoverConfig['ratio']})"><option value="square">方形 1:1</option><option value="portrait">竖版 3:4</option></select></label><div class="save-actions"><button data-testid="save-work" class="acid-button" type="button" :disabled="saving" @click="emit('save',editing?'update':'copy')">{{ editing ? '更新原作（保留创建时间）' : '保存作品' }}</button><button v-if="editing" data-testid="save-copy" class="ghost-button" type="button" :disabled="saving" @click="emit('save','copy')">另存为独立副本</button></div><p v-if="editing" class="save-hint">更新会覆盖当前作品且创建时间不变；另存副本生成一件全新作品，两件可分别修改、删除。</p></div><div class="cover-preview" :class="[config.ratio,config.filter]" :style="{'--c1':config.palette[0],'--c2':config.palette[1],'--c3':config.palette[2]}"><span>SOUND REACTION / 005</span><div class="burst"></div><h3>{{ config.title }}</h3><p>{{ config.bubbleText }}</p><i>▶ PLAY IT</i></div></section></template>
